-- ============================================================================
-- PARTIE 27 — Version e-learning du module 1 : séquence 2/3 (Analyse d'une situation vécue)
-- Source : parties 13 et 23 du module 1 (constellation d'attachement, figures de
-- substitution, doudou, parents), module « Le port d'attache » (Bowlby,
-- Ainsworth, Winnicott) et Charte nationale d'accueil du jeune enfant.
-- Ajoute au thème e-learning créé par la partie 26 une séquence en lecture
-- seule d'environ 25 à 30 minutes : 25 blocs dont 7 questions avec correction,
-- 2 mises en situation, 1 analyse guidée d'un cas (Yanis) et 3 temps de réflexion.
-- LA SÉQUENCE RESTE EN BROUILLON (publie = false).
-- Prérequis : parties 25 et 26 exécutées ; dossier images/module1/ déployé.
-- À exécuter en 3 temps : 27.1, 27.2, puis 27c.
-- Relançable : la séquence n'est créée qu'une fois, et les blocs ne sont ajoutés
-- que si elle n'en contient aucun.
-- Les prénoms (Inès, Hugo, Lina, Léo, Samira, Nadia, Yanis, Amélie) sont ceux de
-- vignettes et d'exemples, pas d'enfants ni de collègues du site.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 27.1 Séquence 2/3 dans le thème e-learning. Attendu : aucune ligne retournée.
-- ---------------------------------------------------------------------------
do $do$
declare tid public.theme.id%type;
begin
  select id into tid from public.theme where nom = $kk$Module 1 – Développement et attachement (e-learning)$kk$;
  if tid is null then raise notice '27.1 : thème e-learning introuvable, exécuter la partie 26'; return; end if;

  if not exists (select 1 from public.module where theme_id = tid and titre = $kk$Module 1 – 2/3 · Analyse d'une situation vécue (e-learning)$kk$) then
    insert into public.module(theme_id, titre, accroche, publie, ordre, trame)
    values (tid, $kk$Module 1 – 2/3 · Analyse d'une situation vécue (e-learning)$kk$,
            $kk$Inès pleure en fin de matinée. Dans les bras de sa référente habituelle, rien n'y fait. Une autre professionnelle la prend : elle s'apaise. **Échec de l'une, chance pour l'autre, ou information précieuse sur ce qui sécurise Inès ?**$kk$,
            false, 1, null);
  end if;
end
$do$;
-- FIN 27.1

-- ---------------------------------------------------------------------------
-- 27.2 Blocs de la séquence. Attendu : aucune ligne retournée (blocs ajoutés une seule fois).
-- ---------------------------------------------------------------------------
do $do$
declare mid public.module.id%type;
begin
  select m.id into mid from public.module m join public.theme t on t.id = m.theme_id
  where t.nom = $kk$Module 1 – Développement et attachement (e-learning)$kk$ and m.titre = $kk$Module 1 – 2/3 · Analyse d'une situation vécue (e-learning)$kk$;
  if mid is null then raise notice '27.2 : séquence introuvable, exécuter 27.1'; return; end if;
  if exists (select 1 from public.bloc where module_id = mid) then raise notice '27.2 : déjà exécuté'; return; end if;

  insert into public.bloc(module_id, type, contenu, ordre)
  select mid, v.type, v.contenu, v.ordre
  from (values
  ('texte', $kk${"titre": "Ce que vous allez faire", "paragraphes": ["Cette séquence prolonge la précédente : après avoir vu pourquoi la sécurité affective vient avant l'exploration, vous allez apprendre à **regarder autour de chaque enfant** pour comprendre qui le sécurise. Comptez **25 à 30 minutes**, à votre rythme.", "Vous y trouverez des situations vécues, **sept questions avec correction**, **deux mises en situation** et une **analyse guidée** d'un cas, étape par étape. Les questions ne sont pas notées. Ce que vous écrivez reste sur votre appareil.", "À la fin, vous saurez décrire la **constellation d'attachement** d'un enfant, repérer s'il a au moins une base stable à la crèche, proposer ce que l'équipe peut faire dans le cas contraire, et en parler avec ses parents."]}$kk$::jsonb, 0),
  ('reflexion', $kk${"question": "Dans la séquence précédente, vous avez peut-être testé un geste (me rendre visible, accueillir chaque venue, observer un enfant). Qu'avez-vous essayé, et qu'avez-vous remarqué chez l'enfant ?", "sous_titre": "Il ne s'agit pas de vous évaluer. Si vous n'avez pas eu l'occasion de tester, notez simplement ce que vous avez observé.", "placeholder": "Écrivez ce qui vous vient. Personne ne lira cette réponse."}$kk$::jsonb, 1),
  ('texte', $kk${"titre": "Une constellation, pas une seule étoile", "paragraphes": ["Pour grandir, un enfant n'a pas besoin d'une seule personne : il a besoin de **plusieurs adultes disponibles**, qu'il choisit. Son attachement est **multiple** : il s'attache à ses parents, à d'autres adultes, parfois à d'autres enfants. On parle de **constellation d'attachement**, dont chaque personne est une étoile.", "Les professionnels qui s'occupent régulièrement de lui sont d'autres étoiles de cette constellation. Cet attachement **ne remplace pas** celui qui le lie à ses parents : il le complète. Et surtout, **ce sont toujours les enfants qui choisissent**.", "Notre rôle n'est donc pas de choisir à sa place. C'est d'**observer vers qui il se tourne**, et d'organiser la crèche pour qu'il trouve au moins une base stable."]}$kk$::jsonb, 2),
  ('question', $kk${"enonce": "Qui choisit les figures d'attachement d'un enfant à la crèche ?", "options": [{"texte": "La direction, en désignant une référente pour chaque enfant", "juste": false}, {"texte": "L'enfant lui-même : l'équipe observe vers qui il se tourne", "juste": true}, {"texte": "Ses parents, au moment de l'inscription", "juste": false}], "explication": "Un enfant peut s'attacher à plusieurs adultes, et ce sont **toujours les enfants qui choisissent**. L'équipe observe, s'organise pour qu'il trouve au moins une base stable et informe les parents. Désigner un adulte reste utile quand un enfant semble perdu (nous y reviendrons), mais ne remplace pas son choix."}$kk$::jsonb, 3),
  ('scenes', $kk${"titre": "Trois situations que vous reconnaîtrez", "items": [{"lettre": "A", "titre": "Elle ne se calme que dans les bras d'une collègue", "texte": "Inès pleure en fin de matinée. Dans les bras de sa référente habituelle, rien n'y fait ; une autre professionnelle la prend et elle s'apaise.", "analyse": "c'est une information, pas un échec. On observe : l'enfant semble choisir une autre figure qui la sécurise plus. L'équipe en parle, en tient compte dans l'organisation et en informe les parents."}, {"lettre": "B", "titre": "Il reste collé et regarde partir chaque adulte", "texte": "Hugo ne quitte pas l'adulte du regard et ne joue que s'il peut le toucher. Dès qu'une collègue se lève, il pleure.", "analyse": "il cherche encore à se sécuriser. On instaure une stabilité affective : un ou deux adultes repères, disponibles, jusqu'à ce qu'il ait assez de sécurité pour jouer. On évite de multiplier les changements d'adulte."}, {"lettre": "C", "titre": "On lui tend le doudou dès qu'il est triste", "texte": "À chaque chagrin, Lina reçoit son doudou en premier. Elle le serre, mais elle cherche encore l'adulte du regard.", "analyse": "le doudou aide à supporter, mais proposé systématiquement il prend la place de l'adulte. L'adulte reste la figure d'attachement : on s'approche, on console par les bras et les mots, et le doudou vient en plus."}]}$kk$::jsonb, 4),
  ('question', $kk${"enonce": "Inès ne se calme que dans les bras d'une collègue, pas dans ceux de sa référente habituelle. Quelle lecture est la plus juste ?", "options": [{"texte": "La référente fait mal son travail : il faut la former", "juste": false}, {"texte": "C'est une information : Inès semble choisir une autre figure qui la sécurise davantage, l'équipe en tient compte", "juste": true}, {"texte": "Inès est capricieuse : elle teste les adultes", "juste": false}], "explication": "Ce n'est pas un échec de la référente, ni un caprice de l'enfant. **L'enfant choisit** : il faut en tenir compte dans l'organisation et en informer les parents."}$kk$::jsonb, 5),
  ('question', $kk${"enonce": "À chaque chagrin, Lina reçoit son doudou en premier, mais elle cherche encore l'adulte du regard. Que faire ?", "options": [{"texte": "Continuer : le doudou est fait pour l'apaiser", "juste": false}, {"texte": "S'approcher, la consoler par les bras et les mots, et laisser le doudou venir en plus", "juste": true}, {"texte": "Retirer le doudou pour qu'elle se tourne vers l'adulte", "juste": false}], "explication": "Le doudou aide à supporter, mais proposé systématiquement il finit par prendre la place de l'adulte, qui reste la figure d'attachement et le meilleur moyen de s'apaiser. On ne le retire pas : on **ajoute** la présence de l'adulte."}$kk$::jsonb, 6),
  ('texte', $kk${"titre": "Observer pour comprendre", "paragraphes": ["Pour décrire la constellation d'un enfant, il faut d'abord **observer sans interpréter** : ce que l'enfant fait, pas ce qu'on croit qu'il ressent. Quelques questions aident à regarder : **vers qui se tourne-t-il** quand il est en difficulté ? **Auprès de qui se calme-t-il**, s'endort-il mieux, cherche-t-il du réconfort ? **Avec qui joue-t-il** ? Dans quels moments de la journée **n'a-t-il pas de repère** ?", "Une précaution : un enfant qui ne pleure pas à la séparation n'est pas forcément serein, il peut avoir appris à cacher son besoin. Il faut regarder **le comportement d'ensemble** plutôt que les seules larmes. Et ces observations décrivent **une relation à un moment donné**, pas une étiquette à poser sur l'enfant."]}$kk$::jsonb, 7),
  ('question', $kk${"enonce": "Parmi ces phrases, lesquelles sont des **observations** (ce que l'on voit), et non des interprétations ? (plusieurs réponses)", "options": [{"texte": "« Hugo ne joue que s'il est contre l'adulte et pleure quand elle se lève. »", "juste": true}, {"texte": "« Hugo est un enfant anxieux. »", "juste": false}, {"texte": "« Inès s'est calmée dans les bras de Nadia au bout de deux minutes. »", "juste": true}, {"texte": "« Inès préfère Nadia parce qu'elle est plus douce. »", "juste": false}], "explication": "Une observation décrit ce qu'on voit ou entend. Les autres phrases **interprètent** (« anxieux », « plus douce ») ou étiquettent. Commencer par décrire protège l'enfant des étiquettes et permet à l'équipe de partager un même regard."}$kk$::jsonb, 8),
  ('texte', $kk${"titre": "Quand l'enfant cherche encore à se sécuriser", "paragraphes": ["Quand un enfant est encore insécure, la première question est : **a-t-il au moins une base stable à la crèche ?** Si le professionnel qui l'accompagne depuis son premier accueil est celui vers qui il se tourne, il **poursuit** son accompagnement. Sinon, l'équipe **observe** s'il choisit une autre personne : il s'endort mieux avec elle, se calme plus dans ses bras.", "S'il semble **perdu**, on **nomme un ou des professionnels** qui deviennent ses figures d'attachement, jusqu'à ce qu'il retrouve assez de sécurité pour jouer. Dans tous les cas, **les parents sont associés et informés**.", "Le but n'est pas de rendre l'enfant dépendant d'un adulte : c'est de lui offrir la sécurité qui lui permettra, ensuite, d'explorer."]}$kk$::jsonb, 9),
  ('comparaison', $kk${"intro": "**Pour accompagner un enfant qui cherche encore à se sécuriser.**", "plutot": ["Observer vers qui l'enfant se tourne et s'en servir dans l'organisation.", "Désigner un adulte stable et disponible lors des premiers accueils.", "Informer les parents et les associer aux décisions.", "Consoler par les bras et par les mots."], "eviter": ["Tarder à répondre à ses signaux.", "Lui imposer un adulte qu'il n'a pas choisi.", "Proposer systématiquement le doudou à la place de l'adulte.", "Changer souvent d'adulte autour de lui."]}$kk$::jsonb, 10),
  ('image', $kk${"url": "images/module1/alliance.jpg", "alt": "Mains d'adultes et main d'enfant superposées", "legende": "Associer et informer les parents : une alliance pour que l'enfant se sente en sécurité."}$kk$::jsonb, 11),
  ('citation', $kk${"texte": "« Je me sens bien accueilli quand ma famille est bien accueillie, car mes parents constituent mon point d'origine et mon port d'attache. »\nCharte nationale d'accueil du jeune enfant"}$kk$::jsonb, 12),
  ('dialogue', $kk${"label": "Mise en situation", "titre": "Informer un parent", "contexte": "17 h. Vous avez observé depuis trois semaines que Léo, 15 mois, se calme surtout dans les bras de Nadia, alors que sa référente est Samira. Sa mère vient le chercher.", "repliques": [{"qui": "La maman de Léo", "texte": "Il court vers Nadia le matin. C'est Samira, sa référente, non ? Il y a un problème avec elle ?"}], "consigne": "Que répondez-vous à cette maman ?", "reponse_modele": "Il n'y a aucun problème : c'est une bonne nouvelle pour Léo. Il choisit les adultes avec qui il se sent le plus en sécurité, et Nadia en fait partie. Samira reste présente pour lui. Nous veillons à ce qu'il retrouve ses repères à chaque moment de la journée. Et vous, vous remarquez quelque chose à la maison ?", "points": ["Dédramatiser sans minimiser : l'enfant choisit, ce n'est pas un échec de la référente.", "Expliquer ce que l'équipe a observé et ce qu'elle met en place.", "Associer le parent : lui demander ce qu'il observe à la maison.", "Rester factuel : décrire ce qu'on a vu, pas ce qu'on croit."]}$kk$::jsonb, 13),
  ('dialogue', $kk${"label": "Mise en situation", "titre": "Une collègue se sent écartée", "contexte": "Pendant la pause, Samira, la référente de Léo, vous confie qu'elle se sent mise de côté.", "repliques": [{"qui": "Samira", "texte": "Il ne veut que Nadia, il me repousse. Je commence à me demander si je suis faite pour ce métier."}], "consigne": "Que lui répondez-vous ?", "reponse_modele": "Ce que tu ressens est normal, et ce n'est pas un jugement sur ton travail. Léo choisit les personnes qui le sécurisent à ce moment-là, et ça peut évoluer. Ce qui compte, c'est qu'il ait au moins une base stable. On pourrait en parler en équipe, pour s'organiser ensemble et voir comment tu peux rester présente pour lui.", "points": ["Accueillir l'émotion de la collègue sans la minimiser.", "Rappeler que le choix de l'enfant n'est pas une évaluation de la compétence.", "Proposer un échange en équipe : on analyse des pratiques, pas des personnes."]}$kk$::jsonb, 14),
  ('texte', $kk${"titre": "Analyser une situation en quatre questions", "paragraphes": ["Quand une situation vous interroge, vous pouvez l'analyser avec l'équipe en **quatre questions**. **Que s'est-il passé ?** On décrit ce que l'on observe, sans interpréter. **Quel besoin de l'enfant ?** A-t-il au moins une base stable à la crèche ? **Que peut faire l'équipe** pour qu'il en trouve une, ou pour élargir sa constellation ? **Que dit-on aux parents, et à quel moment ?**", "On analyse **ce que fait l'adulte, pas ce qu'est l'enfant**. Et on n'écrit ni nom d'enfant ni nom de collègue dans les traces écrites. Essayons ensemble sur un cas, étape par étape."]}$kk$::jsonb, 15),
  ('scenes', $kk${"titre": "Un cas à analyser : Yanis", "items": [{"lettre": "Y", "titre": "Yanis, 16 mois, ne quitte plus la porte des yeux", "texte": "Yanis est accueilli depuis trois semaines. Il jouait volontiers près de sa référente, Amélie. Depuis lundi, Amélie est absente. Yanis ne quitte plus la porte des yeux, refuse de jouer, mange à peine et pleure dès qu'un adulte s'éloigne.", "analyse": "voilà le cas. Vous allez maintenant l'analyser en suivant les quatre questions."}]}$kk$::jsonb, 16),
  ('question', $kk${"enonce": "**Étape 1 : que s'est-il passé ?** Parmi ces formulations, lesquelles décrivent la situation sans l'interpréter ? (plusieurs réponses)", "options": [{"texte": "« Depuis lundi, Yanis refuse de jouer, mange à peine et regarde la porte. »", "juste": true}, {"texte": "« Yanis fait une régression à cause de sa mère. »", "juste": false}, {"texte": "« Il pleure dès qu'un adulte s'éloigne. »", "juste": true}, {"texte": "« Yanis est fragile. »", "juste": false}], "explication": "Les deux premières formulations décrivent ce qui est vu. « Régression à cause de sa mère » et « fragile » sont des **interprétations** qu'on ne peut pas déduire de ce que l'on a observé."}$kk$::jsonb, 17),
  ('question', $kk${"enonce": "**Étape 2 : quel besoin de Yanis ?** Quel besoin semble le plus important ?", "options": [{"texte": "Apprendre à se passer de sa référente", "juste": false}, {"texte": "Retrouver au moins une base stable à la crèche pendant l'absence d'Amélie", "juste": true}, {"texte": "Être occupé par des jeux pour oublier", "juste": false}], "explication": "Yanis a perdu son repère principal. Son besoin est de **retrouver une base stable**. Ce n'est pas le moment de lui demander plus d'autonomie : c'est parce qu'il se sent en sécurité qu'il pourra rejouer."}$kk$::jsonb, 18),
  ('question', $kk${"enonce": "**Étape 3 : que peut faire l'équipe ?** Lesquelles de ces actions sont adaptées ? (plusieurs réponses)", "options": [{"texte": "Observer si Yanis se tourne vers une autre professionnelle, et s'appuyer sur ce choix", "juste": true}, {"texte": "Nommer un ou deux adultes qui seront ses repères pendant l'absence d'Amélie", "juste": true}, {"texte": "Changer d'adulte à chaque moment de la journée pour qu'il s'habitue", "juste": false}, {"texte": "Le consoler par les bras et les mots dès qu'il pleure", "juste": true}], "explication": "On **observe son choix**, on **nomme un ou deux adultes repères**, on **console** par les bras et les mots. Changer souvent d'adulte va à l'encontre de la stabilité dont Yanis a besoin."}$kk$::jsonb, 19),
  ('reflexion', $kk${"question": "**Étape 4 : que dit-on aux parents de Yanis, et à quel moment ?** Écrivez les deux ou trois phrases que vous leur diriez à l'arrivée ou au départ.", "sous_titre": "Il s'agit de décrire ce que vous avez observé et ce que l'équipe met en place. Personne ne lira votre réponse.", "placeholder": "Écrivez ce qui vous vient. Personne ne lira cette réponse."}$kk$::jsonb, 20),
  ('retenir', $kk${"titre": "À retenir", "points": ["**Une constellation, pas une seule étoile :** l'enfant s'attache à plusieurs adultes, et **c'est toujours lui qui choisit**.", "**On observe avant d'interpréter :** vers qui se tourne-t-il, auprès de qui se calme-t-il, avec qui joue-t-il, quand n'a-t-il pas de repère ?", "**Un enfant qui préfère une autre figure** n'est pas un échec pour la référente : c'est une information utile à l'équipe.", "**Un enfant encore insécure a besoin d'au moins une base stable :** on s'appuie sur son choix, ou on nomme un ou deux adultes repères.", "**Le doudou vient en plus de l'adulte, pas à sa place.**", "**Les parents sont associés et informés :** on décrit ce qu'on observe, on ne l'étiquette pas."]}$kk$::jsonb, 21),
  ('essayer', $kk${"label": "À essayer cette semaine", "titre": "Dessiner une constellation", "etapes": [{"titre": "L'enfant au centre.", "texte": "Sans le nommer, dessinez-le au centre d'une feuille."}, {"titre": "Les étoiles.", "texte": "Ajoutez les adultes et les enfants auprès de qui il se calme, joue ou cherche du réconfort."}, {"titre": "Ce qui manque.", "texte": "Repérez les moments de la journée où il n'a pas de repère et décidez d'un geste pour y répondre."}], "note": "On observe des relations, on ne juge personne."}$kk$::jsonb, 22),
  ('reflexion', $kk${"question": "Pour l'enfant que vous avez en tête, qui est dans sa constellation sur le site ? Y a-t-il quelqu'un qui manque ?", "sous_titre": "Il s'agit de décrire, pas de juger. Personne ne lira votre réponse.", "placeholder": "Écrivez ce qui vous vient. Personne ne lira cette réponse."}$kk$::jsonb, 23),
  ('texte', $kk${"titre": "Pour aller plus loin", "paragraphes": ["Dans la séquence suivante, vous verrez comment **préparer les arrivées et les départs** pour qu'ils soient plus sûrs : un adulte disponible sur un jeu, des rituels qui appartiennent aux familles, et une pratique commune à tester en équipe.", "Pour approfondir : **John Bowlby**, « Attachement et perte, tome 1 : l'attachement » (1969) et « Une base de sécurité » (1988) ; **Mary Ainsworth** et ses collègues, « Patterns of Attachment » (1978) ; **Donald W. Winnicott**, « La capacité d'être seul » (1958)."]}$kk$::jsonb, 24)
  ) as v(type, contenu, ordre);

  raise notice '27.2 : 25 blocs ajoutés';
end
$do$;
-- FIN 27.2

-- ---------------------------------------------------------------------------
-- 27c Contrôle (lecture seule). Attendu : séquence 2/3 avec 25 blocs (6 texte, 7 question,
-- 3 reflexion, 2 scenes, 2 dialogue, 1 comparaison, 1 image, 1 citation, 1 retenir,
-- 1 essayer), publie = false, sans trame.
-- ---------------------------------------------------------------------------
select m.titre, m.publie, (m.trame is null) as sans_trame, m.ordre,
       (select count(*) from public.bloc b where b.module_id = m.id) as blocs,
       (select string_agg(x.type || ' ' || x.n, ', ' order by x.type)
          from (select b.type, count(*) as n from public.bloc b where b.module_id = m.id group by b.type) x) as repartition
from public.module m join public.theme t on t.id = m.theme_id
where t.nom = $kk$Module 1 – Développement et attachement (e-learning)$kk$ order by m.ordre;
-- FIN 27c
